CREATE FUNCTION fcBbox AS fc -> tuple(arrayMin(arrayMap(f -> arrayMin(arrayMap(coord -> (coord[1]), JSONExtract(f, 'geometry', 'coordinates', 'Array(Array(Array(Float64)))')[1])), JSONExtractArrayRaw(fc, 'features'))), arrayMax(arrayMap(f -> arrayMax(arrayMap(coord -> (coord[1]), JSONExtract(f, 'geometry', 'coordinates', 'Array(Array(Array(Float64)))')[1])), JSONExtractArrayRaw(fc, 'features'))), arrayMin(arrayMap(f -> arrayMin(arrayMap(coord -> (coord[2]), JSONExtract(f, 'geometry', 'coordinates', 'Array(Array(Array(Float64)))')[1])), JSONExtractArrayRaw(fc, 'features'))), arrayMax(arrayMap(f -> arrayMax(arrayMap(coord -> (coord[2]), JSONExtract(f, 'geometry', 'coordinates', 'Array(Array(Array(Float64)))')[1])), JSONExtractArrayRaw(fc, 'features'))));
